  function enTense(y,topic,diff){
    const n=pick(names);
    if(y<=2){const v=pick(EN_VERB);return Math.random()<.5?mcq('en',topic,`Every day, ${n} ___ ${v[4]}.`,v[2],[v[0],v[1],v[3]],'“Every day” shows a habit. Use the simple present: verb + s.',diff,`pres-${v[0]}`):mcq('en',topic,`Look! The children are ___ ${v[4]} now.`,v[3],[v[0],v[1],v[2]],'“Are … now” needs the -ing form.',diff,`cont-${v[0]}`)}
    if(y<=4){const v=pick(EN_VERB),m=Math.floor(Math.random()*3);if(m===0)return mcq('en',topic,`Yesterday, ${n} ___ ${v[4]}.`,v[1],[v[0],v[2],v[3]],'“Yesterday” needs the past tense.',diff,`past-${v[0]}`);if(m===1)return mcq('en',topic,`Tomorrow, ${n} ___ the museum.`,'will visit',['visited','visits','visiting'],'“Tomorrow” refers to the future: will + verb.',diff,'future-visit');return mcq('en',topic,`Now, ${n} is ___ ${v[4]}.`,v[3],[v[0],v[1],v[2]],'“Is … now” needs the -ing form.',diff,`cont-${v[0]}`)}
    const v=pick(EN_IRR),m=Math.floor(Math.random()*3);
    if(m===0)return mcq('en',topic,`Last week, ${n} ___ to Penang.`,'went',['goes','gone','going'],'The past tense of “go” is “went”.',diff,'irr-go');
    if(m===1)return mcq('en',topic,`Yesterday, ${n} ___ ${v[4]}. (${v[0]})`,v[1],[v[0],v[2],v[3]],`The past tense of “${v[0]}” is “${v[1]}”.`,diff,`irr-${v[0]}`);
    return mcq('en',topic,`${n} has already ___ the homework.`,'finished',['finish','finishes','finishing'],'“Has” + past participle (present perfect).',diff,'perfect-finish');
  }
