  function en(y,topic,diff){
    if(topic==='Vocabulary'){
      const m=Math.random();
      if(y>=3&&m<.25){const r=pick(rowsFor(EN_SYN,y));return mcq('en',topic,`Choose the word closest in meaning to “${r[2]}”.`,r[3],r[4],`“${r[3]}” has a similar meaning to “${r[2]}”.`,diff,`syn-${r[2]}`)}
      if(m<.6){const r=pick(rowsFor(EN_WORD,y));return mcq('en',topic,r[2],r[3],r[4],`The answer is “${r[3]}”.`,diff,`word-${r[3]}`)}
      const r=pick(rowsFor(EN_ANT,y)),pool=rowsFor(EN_ANT,y).flatMap(x=>[x[2],x[3]]).filter(x=>x!==r[3]&&x!==r[2]);return mcq('en',topic,`Choose the opposite of “${r[2]}”.`,r[3],pool,`“${r[3]}” is the opposite of “${r[2]}”.`,diff,`ant-${r[2]}`);
    }
    if(topic==='Tenses')return enTense(y,topic,diff);
    if(topic==='Prepositions'){const r=pick(rowsFor(EN_PREP,y));return mcq('en',topic,r[2],r[3],r[4],`The correct preposition is “${r[3]}”.`,diff,`prep-${r[2]}`)}
    if(topic==='Grammar'){const r=pick(rowsFor(EN_GRAM,y));return mcq('en',topic,r[2],r[3],r[4],r[5],diff,`gram-${r[2]}`)}
    if(topic==='Sentence'){const r=pick(rowsFor(EN_SENT,y));return mcq('en',topic,r[2],r[3],r[4],'Check capital letters, word order and punctuation.',diff,`sent-${r[3]}`)}
    const p=pick(rowsFor(EN_PASS,y)),qa=pick(p[3]);
    return mcq('en','Comprehension',`Read:\n“${p[2]}”\n\n${qa[0]}`,qa[1],qa[2],`The passage tells us: ${qa[1]}`,diff,`comp-${qa[0]}`);
  }

